<script setup lang="ts">
import {computed,ref} from 'vue'
import {BookOpen,Check,Search,X,Pin,Layers} from '@lucide/vue'
import type {Book} from './ledger'
import CategoryIcon from './CategoryIcon.vue'
import {trapDialogTab,useDialogFocus} from './dialogFocus'
const props=withDefaults(defineProps<{books:Book[];modelValue:string[];multiple?:boolean;allowAll?:boolean;appearanceMode?:'system'|'light'|'dark';title?:string}>(),{multiple:false,allowAll:false,appearanceMode:'system',title:'选择账本'})
const emit=defineEmits<{'update:modelValue':[ids:string[]];close:[]}>()
const query=ref(''),dialog=ref<HTMLElement|null>(null)
useDialogFocus(dialog)
const filtered=computed(()=>props.books.filter(book=>[book.name,book.note,book.destination].some(value=>value?.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase()))))
const sections=computed(()=>[{name:'置顶账本',books:filtered.value.filter(book=>book.isPinned)},{name:filtered.value.some(book=>book.isPinned)?'其他账本':'全部账本',books:filtered.value.filter(book=>!book.isPinned)}].filter(section=>section.books.length))
function choose(id:string){emit('update:modelValue',props.multiple?props.modelValue.includes(id)?props.modelValue.filter(value=>value!==id):[...props.modelValue,id]:[id]);if(!props.multiple)emit('close')}
function all(){emit('update:modelValue',[]);emit('close')}
</script>
<template>
  <Teleport to="body"><div class="book-selector-shade" :class="`theme-${appearanceMode}`" @click.self="emit('close')" @keydown.esc.stop.prevent="emit('close')"><section ref="dialog" class="book-selector-dialog" role="dialog" aria-modal="true" :aria-label="title" tabindex="-1" @keydown="trapDialogTab($event,dialog)">
    <header><div><span class="bs-heading-icon"><BookOpen :size="19"/></span><div><h2>{{ title }}</h2><p>{{ multiple?'一笔流水可关联多个账本':'选择账本，查看对应的流水与收支' }}</p></div></div><button type="button" aria-label="关闭账本选择" @click="emit('close')"><X :size="19"/></button></header>
    <label class="bs-search"><Search :size="18"/><input v-model="query" type="search" aria-label="搜索账本" placeholder="搜索账本名称或备注"/><button v-if="query" type="button" aria-label="清除账本搜索" @click="query=''"><X :size="15"/></button></label>
    <div class="bs-options">
      <button v-if="allowAll&&!query.trim()" type="button" class="bs-option bs-all" :class="{selected:!modelValue.length}" :aria-pressed="!modelValue.length" @click="all"><span class="bs-book-icon"><Layers :size="21"/></span><span class="bs-book-copy"><b>全部账本</b><small>查看所有流水，含未关联账本的记录</small></span><Check v-if="!modelValue.length" :size="18"/></button>
      <section v-for="section in sections" :key="section.name" class="bs-group"><h3>{{ section.name }}<span>{{ section.books.length }}</span></h3><button v-for="book in section.books" :key="book.id" type="button" class="bs-option" :class="{selected:modelValue.includes(book.id)}" :aria-pressed="modelValue.includes(book.id)" :aria-label="`选择账本${book.name}`" @click="choose(book.id)"><span class="bs-book-icon" :style="{'--book-color':book.color||'#5799dd'}"><CategoryIcon :name="book.icon||'book'" :color="book.color||'#5799dd'" :size="23"/></span><span class="bs-book-copy"><b :title="book.name">{{ book.name }}</b><small>{{ book.type==='trip'?'旅行账本':'日常账本' }}<template v-if="book.startDate"> · {{ book.startDate.slice(0,10).replaceAll('-','.') }}起</template><template v-else-if="book.note"> · {{ book.note }}</template></small></span><Check v-if="modelValue.includes(book.id)" :size="18"/><Pin v-else-if="book.isPinned" class="bs-pin" :size="14"/><span v-else class="bs-unchecked"></span></button></section>
      <div v-if="!filtered.length" class="bs-empty"><Search :size="27"/><b>{{ query?'没有找到这个账本':'还没有账本' }}</b><p>{{ query?'换个关键词试试':'可以先在账本页创建一个新账本' }}</p></div>
    </div>
    <footer><span>{{ multiple?`已选择 ${modelValue.length} 个账本`:'选择后自动返回流水页' }}</span><button v-if="multiple" type="button" @click="emit('close')">完成选择<Check :size="15"/></button><button v-else-if="modelValue.length" type="button" @click="all">重置为全部</button></footer>
  </section></div></Teleport>
</template>
<style scoped>
.book-selector-shade{--bs-paper:#fff;--bs-soft:#f3f6fb;--bs-line:#e5eaf2;--bs-ink:#233148;--bs-muted:#738198;--bs-accent:#3976d3;--bs-selected:#edf3ff;position:fixed;inset:0;z-index:120;display:flex;align-items:center;justify-content:center;padding:20px;background:#07122288;backdrop-filter:blur(5px);box-sizing:border-box}
.book-selector-shade.theme-dark{--bs-paper:#1b2432;--bs-soft:#202c3c;--bs-line:#2c3a4e;--bs-ink:#e6edf8;--bs-muted:#9cacc2;--bs-accent:#86b3ff;--bs-selected:#263955;color-scheme:dark}
@media(prefers-color-scheme:dark){.book-selector-shade.theme-system{--bs-paper:#1b2432;--bs-soft:#202c3c;--bs-line:#2c3a4e;--bs-ink:#e6edf8;--bs-muted:#9cacc2;--bs-accent:#86b3ff;--bs-selected:#263955;color-scheme:dark}}
.book-selector-dialog{display:flex;flex-direction:column;min-width:0;width:min(480px,100%);max-height:min(760px,calc(100dvh - 40px));overflow:hidden;border:1px solid var(--bs-line);border-radius:23px;background:var(--bs-paper);color:var(--bs-ink);box-shadow:0 25px 90px #07122244;outline:0;font-family:inherit}.book-selector-dialog>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:23px 23px 18px}.book-selector-dialog>header>div{display:flex;align-items:center;gap:12px;min-width:0}.bs-heading-icon{display:grid;place-items:center;flex:none;width:39px;height:39px;border-radius:12px;background:var(--bs-selected);color:var(--bs-accent)}.book-selector-dialog h2{margin:0;font-size:19px;letter-spacing:-.4px}.book-selector-dialog header p{margin:6px 0 0;font-size:11px;line-height:1.7;color:var(--bs-muted)}.book-selector-dialog header>button,.bs-search>button{display:grid;place-items:center;flex:none;width:33px;height:33px;padding:6px;border:0;border-radius:10px;background:var(--bs-soft);color:var(--bs-muted);cursor:pointer}.bs-search{display:flex;align-items:center;gap:9px;flex:none;min-width:0;margin:0 23px 13px;padding:0 12px;border:1px solid var(--bs-line);border-radius:12px;background:var(--bs-soft);color:var(--bs-muted)}.bs-search>svg{flex:none}.bs-search input{width:100%;min-width:0;min-height:44px;margin:0;padding:10px 0;border:0;outline:0;background:transparent;color:var(--bs-ink);font:inherit;font-size:16px;box-sizing:border-box}.bs-search>button{width:26px;height:26px}.bs-options{min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:0 16px 13px}.bs-group h3{display:flex;align-items:center;gap:8px;margin:14px 9px 7px;font-size:10px;font-weight:500;color:var(--bs-muted)}.bs-group h3>span{font-variant-numeric:tabular-nums;opacity:.8}.bs-option{display:flex;align-items:center;gap:12px;width:100%;min-width:0;margin:3px 0;padding:12px 10px;border:1px solid transparent;border-radius:14px;background:transparent;color:var(--bs-ink);font:inherit;text-align:left;cursor:pointer;box-sizing:border-box}.bs-option.selected{border-color:var(--bs-line);background:var(--bs-selected)}.bs-option:hover{background:var(--bs-soft)}.bs-book-icon{display:grid;place-items:center;flex:none;width:43px;height:46px;border:1px solid var(--bs-line);border-radius:13px;background:var(--bs-soft);color:var(--bs-accent)}.bs-book-copy{display:flex;flex:1;flex-direction:column;gap:7px;min-width:0}.bs-book-copy>b{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;font-size:13px;font-weight:600;line-height:1.6;overflow-wrap:anywhere}.bs-book-copy>small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--bs-muted);font-size:10px;line-height:1.5}.bs-option>svg{flex:none;color:var(--bs-accent)}.bs-option>.bs-pin{color:var(--bs-muted)}.bs-unchecked{width:17px;height:17px;flex:none;border:1px solid var(--bs-line);border-radius:50%}.bs-all{margin-bottom:13px;border-color:var(--bs-line)}.bs-empty{display:flex;align-items:center;flex-direction:column;gap:12px;padding:28px 16px;color:var(--bs-muted);text-align:center}.bs-empty>b{font-size:13px;color:var(--bs-ink)}.bs-empty>p{margin:0;font-size:11px}.book-selector-dialog>footer{display:flex;align-items:center;justify-content:space-between;gap:12px;flex:none;min-height:65px;padding:13px 23px;border-top:1px solid var(--bs-line);color:var(--bs-muted);font-size:11px}.book-selector-dialog>footer>button{display:flex;align-items:center;justify-content:center;gap:7px;padding:10px 13px;border:0;border-radius:10px;background:var(--bs-selected);color:var(--bs-accent);font:inherit;font-size:12px;cursor:pointer}.book-selector-dialog button:focus-visible,.bs-search:focus-within{outline:2px solid var(--bs-accent);outline-offset:2px}@media(max-width:600px){.book-selector-shade{align-items:flex-end;padding:12px 10px max(12px,env(safe-area-inset-bottom))}.book-selector-dialog{max-height:calc(100dvh - 28px - env(safe-area-inset-top));border-radius:23px 23px 17px 17px}.book-selector-dialog>header{padding:20px 18px 16px}.bs-search{margin-left:18px;margin-right:18px}.bs-options{padding-left:10px;padding-right:10px}.book-selector-dialog>footer{padding:13px 18px}.bs-heading-icon{width:35px;height:35px}.book-selector-dialog h2{font-size:18px}}
</style>
